#!/usr/bin/env python3
from pathlib import Path
import sys,base64,zlib
root=Path(sys.argv[1] if len(sys.argv)>1 else "upstream")
dec=lambda s:zlib.decompress(base64.b64decode(s)).decode("utf-8")
h=dec("eNodjDsKgDAMQPeeIuCiXsHNwamDVwgmaqFNSvyAiHe3+rbHg1dlwyUhqEzsBBNvGScGJFIZTecQ2XzYGW4HhSA7rCgU2R9YnxqoBd90f/usfAYrl14PIbSrLu1xL/BMIYY=")
cpp=dec("")
(root/"addonProfilerLite.h").write_text(h,encoding="utf-8",newline="\n")
(root/"addonProfilerLite.cpp").write_text(cpp,encoding="utf-8",newline="\n")
make=root/"Makefile";t=make.read_text(encoding="utf-8-sig");n="            performanceProfiling.cpp \\\n"
if "            addonProfilerLite.cpp \\\n" not in t:
    assert n in t,"Makefile marker missing";t=t.replace(n,n+"            addonProfilerLite.cpp \\\n",1)
make.write_text(t,encoding="utf-8",newline="\n")
dll=root/"dllmain.cpp";t=dll.read_text(encoding="utf-8-sig")
if '#include "addonProfilerLite.h"' not in t:
    n='#include "performanceProfiling.h"\n';assert n in t,"dll include marker missing";t=t.replace(n,n+'#include "addonProfilerLite.h"\n',1)
if 'cmd == "profiler"' not in t:
    n='        else if (cmd == "debug") {';assert n in t,"dll command marker missing";t=t.replace(n,'        else if (cmd == "profiler") {\n            return addonProfilerLite::handleLua(L);\n        }\n'+n,1)
dll.write_text(t,encoding="utf-8",newline="\n")
scene=root/"sceneBegin_sceneEnd.cpp";t=scene.read_text(encoding="utf-8-sig")
if '#include "addonProfilerLite.h"' not in t:
    n='#include "FPScap.h"\n';assert n in t,"scene include marker missing";t=t.replace(n,n+'#include "addonProfilerLite.h"\n',1)
if 'addonProfilerLite::onFrameBoundary();' not in t:
    n='    else {\n        scene_isPresenting = false;\n    }\n\n';assert n in t,"scene frame marker missing";t=t.replace(n,n+'    addonProfilerLite::onFrameBoundary();\n\n',1)
scene.write_text(t,encoding="utf-8",newline="\n")
print("AddonProfiler B1R3 Lite applied")
